import functools
from typing import ForwardRef, Dict, Any, Callable
from fastapi import FastAPI
from fastapi.dependencies import utils

# We need a class to define the forward reference in
class MockModel:
    pass

def wrapped_func(a: "MockModel"):
    return a

@functools.wraps(wrapped_func)
def wrapper(a: "MockModel"):
    return wrapped_func(a)

def test_wrapped_method_type_inference():
    # This should not raise NameError
    try:
        sig = utils.get_typed_signature(wrapper)
        print("Successfully got signature")
        print(f"Params: {sig.parameters}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_type_inference()

