import functools
from typing import ForwardRef, Dict, Any, Callable
from fastapi.dependencies import utils
import inspect

# Setup
class MockModel:
    pass

def wrapped_func(a: 'MockModel'):
    return a

@functools.wraps(wrapped_func)
def wrapper(a: 'MockModel'):
    return wrapped_func(a)

# We need to simulate that wrapper is in a different module or its __globals__ 
# is not the one where MockModel is defined.
# Since we can't easily change __globals__, let's try to use a mock object
# that behaves like a wrapped function.

class MockWrapper:
    def __init__(self, wrapped):
        self.__wrapped__ = wrapped
        self.__annotations__ = wrapped.__annotations__
        self.__globals__ = {} # Empty globals
        self.name = 'wrapper'
    def __call__(self, *args, **kwargs):
        return self.__wrapped__(*args, **kwargs)

# Mocking inspect.signature to return what we expect
def mock_signature(obj):
    if isinstance(obj, MockWrapper):
        # Create a dummy signature
        param = inspect.Parameter('a', inspect.Parameter.POSITIONAL_OR_KEYWORD, annotation='MockModel')
        return inspect.Signature([param])
    return inspect.signature(obj)

import fastapi.dependencies.utils
original_inspect_signature = inspect.signature
inspect.signature = mock_signature

wrapper_obj = MockWrapper(wrapped_func)

try:
    sig = utils.get_typed_signature(wrapper_obj)
    print('SUCCESS')
except NameError as e:
    print(f'FAILURE: {e}')
except Exception as e:
    print(f'OTHER ERROR: {e}')
finally:
    inspect.signature = original_inspect_signature
