import functools
from typing import ForwardRef, Dict, Any, Callable
from fastapi.dependencies import utils
import inspect

class MockModel:
    pass

def wrapped_func(a: 'MockModel'):
    return a

@functools.wraps(wrapped_func)
def wrapper(a: 'MockModel'):
    return wrapped_func(a)

# To test the FIX, we need a case that would have FAILED before.
# Before: globalns = getattr(wrapper, '__globals__', {})
# After: globalns = getattr(wrapped_func, '__globals__', {})

# Let's mock __globals__ of wrapper to be empty, but keep wrapped_func's intact.
# Since we can't easily replace __globals__ on a function, we'll use a proxy.

class WrapperProxy:
    def __init__(self, wrapped):
        self.__wrapped__ = wrapped
        self.__annotations__ = wrapped.__annotations__
        self.__globals__ = {}
        self.__name__ = wrapped.__name__

    def __getattr__(self, name):
        return getattr(self.__wrapped__, name)

# Mock inspect.signature for our proxy
def mock_signature(obj):
    if isinstance(obj, WrapperProxy):
        param = inspect.Parameter('a', inspect.Parameter.POSITIONAL_OR_KEYWORD, annotation='MockModel')
        return inspect.Signature([param])
    return inspect.signature(obj)

import fastapi.dependencies.utils
original_inspect_signature = inspect.signature
inspect.signature = mock_signature

proxy = WrapperProxy(wrapped_func)

try:
    sig = utils.get_typed_signature(proxy)
    print('SUCCESS')
except NameError as e:
    print(f'FAILURE: {e}')
except Exception as e:
    print(f'OTHER ERROR: {e}')
finally:
